ALTER TABLE "Pattern" ADD COLUMN "width" INTEGER, ADD COLUMN "height" INTEGER, ADD COLUMN "sourceType" TEXT, ADD COLUMN "kitId" TEXT, ADD COLUMN "mirrored" BOOLEAN NOT NULL DEFAULT false, ADD COLUMN "cells" JSONB, ADD COLUMN "previewPath" TEXT, ADD COLUMN "constructionPath" TEXT, ADD COLUMN "algorithmVersion" TEXT;
CREATE TABLE "PatternConversion" ("id" TEXT NOT NULL, "vaultId" TEXT NOT NULL, "sourceType" TEXT NOT NULL, "status" TEXT NOT NULL, "sourcePath" TEXT NOT NULL, "previewPath" TEXT, "constructionPath" TEXT, "analysis" JSONB NOT NULL, "options" JSONB, "cells" JSONB, "usage" JSONB, "width" INTEGER, "height" INTEGER, "totalBeads" INTEGER, "colorCount" INTEGER, "algorithmVersion" TEXT, "errorCode" TEXT, "expiresAt" TIMESTAMP(3) NOT NULL, "confirmedPatternId" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "PatternConversion_pkey" PRIMARY KEY ("id"));
